let frame;
try { frame = JSON.parse(String(msg.payload)); } catch (error) { return null; }
if (!frame || frame.interface !== 'can1') return null;
msg.payload = JSON.stringify(frame);
msg.topic = 'can_frame';
return msg;

const line = String(msg.payload || '').trim();
if (!line.startsWith('{')) return null;
try {
  const snapshot = JSON.parse(line);
  if (!snapshot || snapshot.source !== 'rs485-dyness') return null;
  flow.set('balancerRs485Snapshot', snapshot);
  if (snapshot.valid === true) flow.set('balancerRs485LastValidSnapshot', snapshot);
  msg.topic = 'rs485';
  msg.payload = snapshot;
  return msg;
} catch (error) { node.warn(`invalid RS485 JSON: ${error.message}`); return null; }

const value = Number(msg.payload);
const desired = Number(flow.get("cwhVirtualSwitchDesired"));
if (![0, 1].includes(value) || ![0, 1].includes(desired)) return null;
if (value === desired) return null;
msg.topic = value === 1 ? "manual_start" : "manual_stop";
return msg;

const state = msg.hot_water && msg.hot_water.state;
if (!state) return null;
const desired = state === "HEATING" ? 1 : 0;
const previous = flow.get("cwhVirtualSwitchDesired");
flow.set("cwhVirtualSwitchDesired", desired);
if (previous === desired) return null;
return {
  topic: "virtual_switch_sync",
  payload: { "SwitchableOutput/output_1/State": desired }
};

// Generated from src/controller.js. Do not edit this field manually.
const TEST_MODE = false;
const RUNTIME_VERSION = 6;
'use strict'

const CONFIG = Object.freeze({
  QUALIFICATION_MS: 5 * 60 * 1000,
  EARLY_MANUAL_CANCEL_MS: 5 * 60 * 1000,
  HEATING_DURATION_MS: (3 * 60 + 30) * 60 * 1000,
  INPUT_STALE_MS: 6 * 60 * 1000,
  THERMOSTAT_BLANKING_MS: 10 * 60 * 1000,
  CONSUMPTION_THRESHOLD_W: 2000,
  CONSUMPTION_LOW_CYCLES_REQUIRED: 2,
  CONSUMPTION_STALE_MS: 90 * 1000,
  DEFAULT_HEATING_POWER_W: 1910,
  MIN_HEATING_POWER_W: 1,
  MAX_HEATING_POWER_W: 10000,
  SOC_THRESHOLD: 95,
  PV_THRESHOLD_W: 100,
  STATE_VERSION: 5
})

const SCHEDULE_MODES = Object.freeze({
  AUTO: 'AUTO',
  MANUAL: 'MANUAL'
})

const ENERGY_TRACKING_STATES = Object.freeze({
  INACTIVE: 'INACTIVE',
  ACTIVE: 'ACTIVE',
  PAUSED: 'PAUSED'
})

const STATES = Object.freeze({
  WAITING: 'WAITING',
  QUALIFYING: 'QUALIFYING',
  HEATING: 'HEATING',
  FINISHED_TODAY: 'FINISHED_TODAY',
  FAULT_SAFE: 'FAULT_SAFE'
})

const STATUS_LABELS = Object.freeze({
  WAITING: 'Waiting',
  QUALIFYING: 'Qualifying',
  HEATING: 'Heating',
  FINISHED_TODAY: 'Finished today',
  FAULT_SAFE: 'Fault'
})

function emptyState () {
  return {
    version: CONFIG.STATE_VERSION,
    state: STATES.WAITING,
    schedule_mode: SCHEDULE_MODES.MANUAL,
    last_cycle_date: null,
    heating_started_at: null,
    heating_deadline: null,
    qualification_started_at: null,
    start_source: null,
    thermostat_low_cycles: 0,
    completion_reason: null,
    heating_power_w: CONFIG.DEFAULT_HEATING_POWER_W,
    daily_energy_date: null,
    daily_completed_energy_kwh: 0,
    active_cycle_power_w: null,
    active_cycle_tracked_ms: 0,
    active_cycle_tracked_today_ms: 0,
    active_cycle_tracking_date: null,
    active_cycle_tracking_started_at: null,
    active_cycle_energy_tracking_state: ENERGY_TRACKING_STATES.INACTIVE,
    active_cycle_energy_pause_reason: 'NOT_HEATING',
    latest_cycle: null,
    heating_power_result: null,
    schedule_mode_result: null,
    last_commanded_relay_state: 0
  }
}

function isFiniteNumber (value) {
  return typeof value === 'number' && Number.isFinite(value)
}

function localDate (timestamp) {
  const date = new Date(timestamp)
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

function pad2 (value) {
  return String(value).padStart(2, '0')
}

function formatClock (timestamp) {
  if (!isFiniteNumber(timestamp)) return '—'
  const date = new Date(timestamp)
  return `${pad2(date.getHours())}:${pad2(date.getMinutes())}`
}

function formatDuration (milliseconds) {
  if (!isFiniteNumber(milliseconds)) return '—'
  const totalMinutes = Math.max(0, Math.floor(milliseconds / 60000))
  const hours = Math.floor(totalMinutes / 60)
  const minutes = totalMinutes % 60
  return `${pad2(hours)}:${pad2(minutes)}`
}

function formatSeconds (milliseconds) {
  if (!isFiniteNumber(milliseconds)) return '—'
  const totalSeconds = Math.max(0, Math.ceil(milliseconds / 1000))
  const minutes = Math.floor(totalSeconds / 60)
  const seconds = totalSeconds % 60
  return `${pad2(minutes)}:${pad2(seconds)}`
}

function formatDateTime (timestamp) {
  if (!isFiniteNumber(timestamp)) return '—'
  return `${localDate(timestamp)} ${formatClock(timestamp)}`
}

function localDateBounds (dateText) {
  if (typeof dateText !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dateText)) return null
  const [year, month, day] = dateText.split('-').map(Number)
  const start = new Date(year, month - 1, day).getTime()
  const end = new Date(year, month - 1, day + 1).getTime()
  return { start, end }
}

function intervalOverlapMsForLocalDate (start, end, dateText) {
  if (!isFiniteNumber(start) || !isFiniteNumber(end) || end <= start) return 0
  const bounds = localDateBounds(dateText)
  if (!bounds) return 0
  return Math.max(0, Math.min(end, bounds.end) - Math.max(start, bounds.start))
}

function energyKwh (milliseconds, powerW) {
  if (!isFiniteNumber(milliseconds) || milliseconds <= 0 ||
      !isFiniteNumber(powerW) || powerW <= 0) return 0
  return milliseconds * powerW / 3600000000
}

function validateState (candidate) {
  if (!candidate || typeof candidate !== 'object') {
    throw new Error('persistent state is not an object')
  }

  if (!Object.values(STATES).includes(candidate.state)) {
    throw new Error(`unknown state: ${candidate.state}`)
  }

  const scheduleMode = candidate.schedule_mode === undefined
    ? SCHEDULE_MODES.MANUAL
    : candidate.schedule_mode
  if (!Object.values(SCHEDULE_MODES).includes(scheduleMode)) {
    throw new Error(`invalid schedule_mode: ${scheduleMode}`)
  }

  if (candidate.last_cycle_date !== null &&
      !/^\d{4}-\d{2}-\d{2}$/.test(candidate.last_cycle_date)) {
    throw new Error('invalid last_cycle_date')
  }

  if (![0, 1].includes(candidate.last_commanded_relay_state)) {
    throw new Error('invalid last_commanded_relay_state')
  }

  if (candidate.thermostat_low_cycles !== undefined &&
      (!Number.isInteger(candidate.thermostat_low_cycles) ||
       candidate.thermostat_low_cycles < 0 ||
       candidate.thermostat_low_cycles > CONFIG.CONSUMPTION_LOW_CYCLES_REQUIRED)) {
    throw new Error('invalid thermostat_low_cycles')
  }

  if (candidate.completion_reason !== undefined &&
      candidate.completion_reason !== null &&
      typeof candidate.completion_reason !== 'string') {
    throw new Error('invalid completion_reason')
  }

  const heatingPower = candidate.heating_power_w === undefined
    ? CONFIG.DEFAULT_HEATING_POWER_W
    : candidate.heating_power_w
  if (!isFiniteNumber(heatingPower) || heatingPower < CONFIG.MIN_HEATING_POWER_W ||
      heatingPower > CONFIG.MAX_HEATING_POWER_W) {
    throw new Error('invalid heating_power_w')
  }

  if (candidate.daily_energy_date !== undefined && candidate.daily_energy_date !== null &&
      !/^\d{4}-\d{2}-\d{2}$/.test(candidate.daily_energy_date)) {
    throw new Error('invalid daily_energy_date')
  }

  if (candidate.daily_completed_energy_kwh !== undefined &&
      (!isFiniteNumber(candidate.daily_completed_energy_kwh) || candidate.daily_completed_energy_kwh < 0)) {
    throw new Error('invalid daily_completed_energy_kwh')
  }

  if (candidate.active_cycle_power_w !== undefined && candidate.active_cycle_power_w !== null &&
      (!isFiniteNumber(candidate.active_cycle_power_w) ||
       candidate.active_cycle_power_w < CONFIG.MIN_HEATING_POWER_W ||
       candidate.active_cycle_power_w > CONFIG.MAX_HEATING_POWER_W)) {
    throw new Error('invalid active_cycle_power_w')
  }

  const trackedMs = candidate.active_cycle_tracked_ms === undefined
    ? 0
    : candidate.active_cycle_tracked_ms
  const trackedTodayMs = candidate.active_cycle_tracked_today_ms === undefined
    ? 0
    : candidate.active_cycle_tracked_today_ms
  if (!isFiniteNumber(trackedMs) || trackedMs < 0 ||
      !isFiniteNumber(trackedTodayMs) || trackedTodayMs < 0 || trackedTodayMs > trackedMs) {
    throw new Error('invalid active cycle tracking duration')
  }
  const trackingDate = candidate.active_cycle_tracking_date === undefined
    ? null
    : candidate.active_cycle_tracking_date
  if (trackingDate !== null && !/^\d{4}-\d{2}-\d{2}$/.test(trackingDate)) {
    throw new Error('invalid active_cycle_tracking_date')
  }
  const trackingStartedAt = candidate.active_cycle_tracking_started_at === undefined
    ? null
    : candidate.active_cycle_tracking_started_at
  if (trackingStartedAt !== null && !isFiniteNumber(trackingStartedAt)) {
    throw new Error('invalid active_cycle_tracking_started_at')
  }
  const trackingState = candidate.active_cycle_energy_tracking_state === undefined
    ? ENERGY_TRACKING_STATES.INACTIVE
    : candidate.active_cycle_energy_tracking_state
  if (!Object.values(ENERGY_TRACKING_STATES).includes(trackingState)) {
    throw new Error('invalid active_cycle_energy_tracking_state')
  }
  const pauseReason = candidate.active_cycle_energy_pause_reason === undefined
    ? 'NOT_HEATING'
    : candidate.active_cycle_energy_pause_reason
  if (pauseReason !== null && typeof pauseReason !== 'string') {
    throw new Error('invalid active_cycle_energy_pause_reason')
  }

  if (candidate.latest_cycle !== undefined && candidate.latest_cycle !== null) {
    const cycle = candidate.latest_cycle
    if (!cycle || !isFiniteNumber(cycle.started_at) || !isFiniteNumber(cycle.ended_at) ||
        cycle.ended_at < cycle.started_at || !isFiniteNumber(cycle.duration_ms) ||
        cycle.duration_ms < 0 || !isFiniteNumber(cycle.power_w) || cycle.power_w <= 0 ||
        !isFiniteNumber(cycle.energy_kwh) || cycle.energy_kwh < 0 ||
        typeof cycle.source !== 'string' || typeof cycle.completion_reason !== 'string') {
      throw new Error('invalid latest_cycle')
    }
  }

  for (const field of ['heating_started_at', 'heating_deadline', 'qualification_started_at']) {
    if (candidate[field] !== null && !isFiniteNumber(candidate[field])) {
      throw new Error(`invalid ${field}`)
    }
  }

  if (candidate.state === STATES.HEATING) {
    if (!isFiniteNumber(candidate.heating_started_at) ||
        !isFiniteNumber(candidate.heating_deadline) ||
        candidate.heating_deadline <= candidate.heating_started_at) {
      throw new Error('heating state has no valid immutable deadline')
    }
  }

  if (candidate.state === STATES.QUALIFYING &&
      !isFiniteNumber(candidate.qualification_started_at)) {
    throw new Error('qualifying state has no start timestamp')
  }

  const validated = {
    ...emptyState(),
    ...candidate,
    schedule_mode: scheduleMode,
    heating_power_w: heatingPower,
    active_cycle_tracked_ms: trackedMs,
    active_cycle_tracked_today_ms: trackedTodayMs,
    active_cycle_tracking_date: trackingDate,
    active_cycle_tracking_started_at: trackingStartedAt,
    active_cycle_energy_tracking_state: trackingState,
    active_cycle_energy_pause_reason: pauseReason,
    version: CONFIG.STATE_VERSION
  }
  if (validated.state === STATES.HEATING && validated.active_cycle_power_w === null) {
    validated.active_cycle_power_w = heatingPower
  }
  return validated
}

function createHotWaterController (options = {}) {
  const now = options.now || (() => Date.now())
  const dateOf = options.localDate || localDate
  let state = emptyState()
  let loaded = false
  let relayReasserted = false
  const inputs = {
    soc: { value: null, at: null },
    pv: { value: null, at: null },
    consumptionPhaseCount: { value: null, at: null },
    consumptionL1: { value: null, at: null },
    consumptionL2: { value: null, at: null },
    consumptionL3: { value: null, at: null }
  }

  function consumptionAggregate (timestamp) {
    const countInput = inputs.consumptionPhaseCount
    const phaseCountValid = Number.isInteger(countInput.value) &&
      countInput.value >= 1 && countInput.value <= 3 &&
      isFiniteNumber(countInput.at) &&
      timestamp - countInput.at <= CONFIG.CONSUMPTION_STALE_MS
    const phaseCount = phaseCountValid ? countInput.value : null
    const phaseInputs = [inputs.consumptionL1, inputs.consumptionL2, inputs.consumptionL3]
    const phases = phaseInputs.map((input, index) => {
      const expected = phaseCount !== null && index < phaseCount
      const fresh = isFiniteNumber(input.value) && input.value >= 0 &&
        isFiniteNumber(input.at) &&
        timestamp - input.at <= CONFIG.CONSUMPTION_STALE_MS
      return {
        phase: index + 1,
        expected,
        value: isFiniteNumber(input.value) && input.value >= 0 ? input.value : null,
        fresh
      }
    })
    const expectedPhases = phases.filter(phase => phase.expected)
    const valid = phaseCount !== null && expectedPhases.length === phaseCount &&
      expectedPhases.every(phase => phase.fresh)
    const sampleTimes = phaseCount === null
      ? []
      : [countInput, ...phaseInputs.slice(0, phaseCount)].map(input => input.at)
    const sampleAt = sampleTimes.length > 0 && sampleTimes.every(isFiniteNumber)
      ? Math.min(...sampleTimes)
      : null
    return {
      valid,
      phaseCount,
      phases,
      total: valid ? expectedPhases.reduce((sum, phase) => sum + phase.value, 0) : null,
      sample_at: sampleAt
    }
  }

  function status (timestamp, note = '', remainingOverride) {
    const remaining = remainingOverride === undefined
      ? (state.state === STATES.HEATING && isFiniteNumber(state.heating_deadline)
          ? Math.max(0, state.heating_deadline - timestamp)
          : null)
      : remainingOverride

    const consumption = consumptionAggregate(timestamp)
    const heatingElapsed = state.state === STATES.HEATING && isFiniteNumber(state.heating_started_at)
      ? Math.max(0, timestamp - state.heating_started_at)
      : null
    const blankingRemaining = heatingElapsed !== null
      ? Math.max(0, CONFIG.THERMOSTAT_BLANKING_MS - heatingElapsed)
      : null
    let thermostatMonitor = 'Not monitoring'
    if (state.completion_reason === 'THERMOSTAT_DEMAND_ENDED') {
      thermostatMonitor = 'Thermostat demand ended'
    } else if (state.state === STATES.HEATING && blankingRemaining > 0) {
      thermostatMonitor = 'Startup blanking'
    } else if (state.state === STATES.HEATING && !consumption.valid) {
      thermostatMonitor = 'Consumption input unavailable'
    } else if (state.state === STATES.HEATING && state.thermostat_low_cycles > 0) {
      thermostatMonitor = `Low consumption ${state.thermostat_low_cycles}/${CONFIG.CONSUMPTION_LOW_CYCLES_REQUIRED}`
    } else if (state.state === STATES.HEATING) {
      thermostatMonitor = 'Heating demand present'
    }

    const today = dateOf(timestamp)
    const completedToday = state.daily_energy_date === today
      ? state.daily_completed_energy_kwh
      : 0
    const activeTodayMs = state.state === STATES.HEATING
      ? state.active_cycle_tracked_today_ms
      : 0
    const activeTodayEnergy = energyKwh(activeTodayMs, state.active_cycle_power_w)
    const activeCycleElapsed = state.state === STATES.HEATING && isFiniteNumber(state.heating_started_at)
      ? Math.max(0, timestamp - state.heating_started_at)
      : null
    const activeCycleEnergy = energyKwh(state.active_cycle_tracked_ms, state.active_cycle_power_w)
    const latest = state.latest_cycle

    let scheduleBehavior
    if (state.state === STATES.FAULT_SAFE) {
      scheduleBehavior = 'Fault-safe controller state; automatic scheduling is unavailable.'
    } else if (state.state === STATES.HEATING) {
      scheduleBehavior = 'Current heating cycle continues unchanged; selected schedule mode applies after completion.'
    } else if (state.state === STATES.FINISHED_TODAY) {
      scheduleBehavior = 'Heating finished today; automatic scheduling will not restart today.'
    } else if (state.schedule_mode === SCHEDULE_MODES.MANUAL) {
      scheduleBehavior = 'Automatic daily schedule paused; manual Start permitted.'
    } else if (state.state === STATES.QUALIFYING) {
      scheduleBehavior = 'Automatic start qualification in progress.'
    } else {
      scheduleBehavior = 'Automatic daily schedule enabled; waiting for SOC/PV qualification.'
    }

    return {
      state: state.state,
      label: STATUS_LABELS[state.state],
      schedule_mode: state.schedule_mode,
      automatic_schedule_enabled: state.schedule_mode === SCHEDULE_MODES.AUTO,
      schedule_behavior: scheduleBehavior,
      status_timestamp: timestamp,
      status_updated_at_text: formatDateTime(timestamp),
      note,
      mode: 'TEST_MODE',
      date: dateOf(timestamp),
      start_source: state.start_source,
      heating_started_at: state.heating_started_at,
      heating_deadline: state.heating_deadline,
      remaining_ms: remaining,
      heating_started_at_text: formatClock(state.heating_started_at),
      heating_deadline_text: formatClock(state.heating_deadline),
      remaining_text: formatDuration(remaining),
      soc: inputs.soc.value,
      pv_power_w: inputs.pv.value,
      soc_fresh: isFresh(inputs.soc, timestamp),
      pv_fresh: isFresh(inputs.pv, timestamp),
      consumption_phase_count: consumption.phaseCount,
      consumption_phases: consumption.phases,
      house_consumption_w: consumption.total,
      house_consumption_valid: consumption.valid,
      thermostat_monitor: thermostatMonitor,
      thermostat_low_cycles: state.thermostat_low_cycles,
      thermostat_low_cycles_required: CONFIG.CONSUMPTION_LOW_CYCLES_REQUIRED,
      thermostat_blanking_remaining_ms: blankingRemaining,
      thermostat_blanking_remaining_text: blankingRemaining === null ? '—' : formatSeconds(blankingRemaining),
      completion_reason: state.completion_reason,
      heating_power_w: state.heating_power_w,
      active_cycle_power_w: state.active_cycle_power_w,
      active_cycle_consumption_threshold_w: state.active_cycle_power_w,
      active_cycle_energy_tracking_state: state.active_cycle_energy_tracking_state,
      active_cycle_energy_pause_reason: state.active_cycle_energy_pause_reason,
      active_cycle_tracked_ms: state.active_cycle_tracked_ms,
      active_cycle_tracked_text: formatDuration(state.active_cycle_tracked_ms),
      today_consumption_kwh: completedToday + activeTodayEnergy,
      completed_today_consumption_kwh: completedToday,
      active_cycle_elapsed_ms: activeCycleElapsed,
      active_cycle_elapsed_text: formatDuration(activeCycleElapsed),
      active_cycle_energy_kwh: activeCycleEnergy,
      latest_cycle: latest
        ? {
            ...latest,
            started_at_text: formatDateTime(latest.started_at),
            ended_at_text: formatDateTime(latest.ended_at),
            duration_text: formatDuration(latest.duration_ms)
          }
        : null,
      heating_power_result: state.heating_power_result,
      schedule_mode_result: state.schedule_mode_result
    }
  }

  function isFresh (input, timestamp) {
    return isFiniteNumber(input.value) && isFiniteNumber(input.at) &&
      timestamp - input.at <= CONFIG.INPUT_STALE_MS
  }

  function conditionsValid (timestamp) {
    return isFresh(inputs.soc, timestamp) &&
      isFresh(inputs.pv, timestamp) &&
      inputs.soc.value >= CONFIG.SOC_THRESHOLD &&
      inputs.pv.value > CONFIG.PV_THRESHOLD_W
  }

  function actionSet () {
    return []
  }

  function persist (actions) {
    actions.push({ type: 'persist', state: { ...state } })
  }

  function rollDailyEnergy (timestamp, actions) {
    const today = dateOf(timestamp)
    if (state.daily_energy_date === today) return false
    state.daily_energy_date = today
    state.daily_completed_energy_kwh = 0
    if (state.state === STATES.HEATING) {
      state.active_cycle_tracked_today_ms = 0
      state.active_cycle_tracking_date = today
    }
    persist(actions)
    return true
  }

  function updateActiveCycleTracking (timestamp, actions) {
    if (state.state !== STATES.HEATING || !isFiniteNumber(state.active_cycle_power_w)) return

    const consumption = consumptionAggregate(timestamp)
    const eligible = consumption.valid && consumption.total >= state.active_cycle_power_w
    const segmentEnd = consumption.valid || !isFiniteNumber(consumption.sample_at)
      ? timestamp
      : Math.min(timestamp, consumption.sample_at + CONFIG.CONSUMPTION_STALE_MS)
    let changed = false

    if (isFiniteNumber(state.active_cycle_tracking_started_at) && segmentEnd > state.active_cycle_tracking_started_at) {
      const segmentStart = state.active_cycle_tracking_started_at
      state.active_cycle_tracked_ms += segmentEnd - segmentStart
      state.active_cycle_tracked_today_ms += intervalOverlapMsForLocalDate(
        segmentStart,
        segmentEnd,
        state.daily_energy_date
      )
      changed = true
    }

    const nextStartedAt = eligible ? timestamp : null
    const nextState = eligible ? ENERGY_TRACKING_STATES.ACTIVE : ENERGY_TRACKING_STATES.PAUSED
    const nextReason = eligible ? null : consumption.valid
      ? 'HOUSE_CONSUMPTION_BELOW_THRESHOLD'
      : 'HOUSE_CONSUMPTION_UNAVAILABLE'
    if (state.active_cycle_tracking_started_at !== nextStartedAt ||
        state.active_cycle_energy_tracking_state !== nextState ||
        state.active_cycle_energy_pause_reason !== nextReason) {
      state.active_cycle_tracking_started_at = nextStartedAt
      state.active_cycle_energy_tracking_state = nextState
      state.active_cycle_energy_pause_reason = nextReason
      changed = true
    }

    if (changed) persist(actions)
  }

  function finalizeActiveCycle (timestamp, actions, completionReason) {
    if (state.state !== STATES.HEATING || !isFiniteNumber(state.heating_started_at) ||
        !isFiniteNumber(state.active_cycle_power_w)) return false
    const startedAt = state.heating_started_at
    const endedAt = Math.max(startedAt, timestamp)
    const durationMs = endedAt - startedAt
    const powerW = state.active_cycle_power_w
    const source = state.start_source || 'unknown'
    rollDailyEnergy(endedAt, actions)
    updateActiveCycleTracking(endedAt, actions)
    state.daily_completed_energy_kwh += energyKwh(state.active_cycle_tracked_today_ms, powerW)
    state.latest_cycle = {
      started_at: startedAt,
      ended_at: endedAt,
      duration_ms: durationMs,
      power_w: powerW,
      energy_kwh: energyKwh(state.active_cycle_tracked_ms, powerW),
      source,
      completion_reason: completionReason
    }
    state.active_cycle_power_w = null
    state.active_cycle_tracked_ms = 0
    state.active_cycle_tracked_today_ms = 0
    state.active_cycle_tracking_date = null
    state.active_cycle_tracking_started_at = null
    state.active_cycle_energy_tracking_state = ENERGY_TRACKING_STATES.INACTIVE
    state.active_cycle_energy_pause_reason = 'NOT_HEATING'
    return true
  }

  function transition (nextState, timestamp, actions, note) {
    if (state.state === nextState) return false
    state.state = nextState
    if (nextState !== STATES.QUALIFYING) state.qualification_started_at = null
    if (nextState !== STATES.HEATING) {
      state.heating_started_at = null
      state.heating_deadline = null
      state.start_source = null
    }
    persist(actions)
    actions.push({ type: 'status', status: status(timestamp, note) })
    return true
  }

  function commandRelay (value, timestamp, actions, reason) {
    if (value !== 0 && value !== 1) throw new Error('invalid relay command')
    if (value === state.last_commanded_relay_state && relayReasserted) return
    state.last_commanded_relay_state = value
    relayReasserted = true
    actions.push({ type: 'relay', value, reason })
    persist(actions)
    actions.push({ type: 'status', status: status(timestamp, reason) })
  }

  function clearHeatingFields () {
    state.heating_started_at = null
    state.heating_deadline = null
    state.qualification_started_at = null
    state.start_source = null
    state.thermostat_low_cycles = 0
  }

  function startHeating (source, timestamp, actions) {
    state.state = STATES.HEATING
    state.last_cycle_date = dateOf(timestamp)
    state.heating_started_at = timestamp
    state.heating_deadline = timestamp + CONFIG.HEATING_DURATION_MS
    state.qualification_started_at = null
    state.start_source = source
    state.active_cycle_power_w = state.heating_power_w
    state.active_cycle_tracked_ms = 0
    state.active_cycle_tracked_today_ms = 0
    state.active_cycle_tracking_date = dateOf(timestamp)
    state.active_cycle_tracking_started_at = null
    state.active_cycle_energy_tracking_state = ENERGY_TRACKING_STATES.PAUSED
    state.active_cycle_energy_pause_reason = 'HOUSE_CONSUMPTION_UNAVAILABLE'
    state.thermostat_low_cycles = 0
    state.completion_reason = null
    updateActiveCycleTracking(timestamp, actions)
    persist(actions)
    commandRelay(1, timestamp, actions, `${source} cycle started`)
    actions.push({ type: 'status', status: status(timestamp, `${source} cycle started`) })
  }

  function finishToday (timestamp, actions, note, completionReason = null) {
    const remaining = state.state === STATES.HEATING && isFiniteNumber(state.heating_deadline)
      ? Math.max(0, state.heating_deadline - timestamp)
      : null
    finalizeActiveCycle(timestamp, actions, completionReason || 'FINISHED_TODAY')
    state.state = STATES.FINISHED_TODAY
    state.last_cycle_date = dateOf(timestamp)
    clearHeatingFields()
    state.completion_reason = completionReason
    if (completionReason === 'THERMOSTAT_DEMAND_ENDED') {
      state.thermostat_low_cycles = CONFIG.CONSUMPTION_LOW_CYCLES_REQUIRED
    }
    persist(actions)
    commandRelay(0, timestamp, actions, note)
    actions.push({ type: 'status', status: status(timestamp, note, remaining) })
  }

  function cancelManualCycle (timestamp, actions) {
    finalizeActiveCycle(timestamp, actions, 'EARLY_MANUAL_CANCEL')
    state.state = STATES.WAITING
    state.last_cycle_date = null
    clearHeatingFields()
    state.completion_reason = null
    persist(actions)
    commandRelay(0, timestamp, actions, 'manual cycle cancelled within five minutes')
    actions.push({ type: 'status', status: status(timestamp, 'manual cycle cancelled; waiting') })
  }

  function resetForNewDay (timestamp, actions) {
    if (state.state !== STATES.FINISHED_TODAY || state.last_cycle_date === dateOf(timestamp)) return
    state.state = STATES.WAITING
    state.last_cycle_date = null
    state.thermostat_low_cycles = 0
    state.completion_reason = null
    persist(actions)
    actions.push({ type: 'status', status: status(timestamp, 'new local calendar day') })
  }

  function evaluateThermostatTick (timestamp, actions) {
    const elapsed = timestamp - state.heating_started_at
    if (elapsed < CONFIG.THERMOSTAT_BLANKING_MS) {
      if (state.thermostat_low_cycles !== 0) {
        state.thermostat_low_cycles = 0
        persist(actions)
      }
      return false
    }

    const consumption = consumptionAggregate(timestamp)
    if (!consumption.valid || consumption.total >= CONFIG.CONSUMPTION_THRESHOLD_W) {
      if (state.thermostat_low_cycles !== 0) {
        state.thermostat_low_cycles = 0
        persist(actions)
      }
      return false
    }

    state.thermostat_low_cycles = Math.min(
      CONFIG.CONSUMPTION_LOW_CYCLES_REQUIRED,
      state.thermostat_low_cycles + 1
    )
    persist(actions)
    if (state.thermostat_low_cycles >= CONFIG.CONSUMPTION_LOW_CYCLES_REQUIRED) {
      finishToday(
        timestamp,
        actions,
        'internal thermostat demand ended',
        'THERMOSTAT_DEMAND_ENDED'
      )
      return true
    }
    return false
  }

  function evaluate (timestamp, actions, options = {}) {
    if (!loaded) return

    if (state.state === STATES.FAULT_SAFE) {
      commandRelay(0, timestamp, actions, 'fault-safe output')
      actions.push({ type: 'status', status: status(timestamp, 'invalid or corrupted persistent state') })
      return
    }

    resetForNewDay(timestamp, actions)
    rollDailyEnergy(timestamp, actions)
    updateActiveCycleTracking(timestamp, actions)

    if (state.state === STATES.HEATING) {
      if (timestamp >= state.heating_deadline) {
        finishToday(timestamp, actions, 'heating deadline reached', 'HEATING_DEADLINE_REACHED')
      } else if (options.thermostatTick && evaluateThermostatTick(timestamp, actions)) {
        return
      } else {
        commandRelay(1, timestamp, actions, 'heating deadline active')
        actions.push({ type: 'status', status: status(timestamp) })
      }
      return
    }

    if (state.last_cycle_date === dateOf(timestamp)) {
      if (state.state !== STATES.FINISHED_TODAY) finishToday(timestamp, actions, 'cycle already completed today')
      else commandRelay(0, timestamp, actions, 'finished today')
      return
    }

    commandRelay(0, timestamp, actions, 'waiting output')

    if (state.schedule_mode === SCHEDULE_MODES.MANUAL) {
      if (state.state === STATES.QUALIFYING) {
        state.state = STATES.WAITING
        state.qualification_started_at = null
        persist(actions)
      }
      actions.push({
        type: 'status',
        status: status(timestamp, 'automatic schedule paused; manual start permitted')
      })
      return
    }

    if (state.state === STATES.QUALIFYING) {
      if (!conditionsValid(timestamp)) {
        transition(STATES.WAITING, timestamp, actions, 'qualification reset')
      } else if (timestamp - state.qualification_started_at >= CONFIG.QUALIFICATION_MS) {
        startHeating('automatic', timestamp, actions)
      } else {
        actions.push({ type: 'status', status: status(timestamp) })
      }
      return
    }

    if (conditionsValid(timestamp)) {
      state.state = STATES.QUALIFYING
      state.qualification_started_at = timestamp
      persist(actions)
      actions.push({ type: 'status', status: status(timestamp, 'SOC and PV qualification started') })
    } else {
      actions.push({ type: 'status', status: status(timestamp) })
    }
  }

  function handle (message) {
    const timestamp = now()
    const actions = actionSet()
    const type = message && message.type

    if (type === 'load') {
      try {
        state = message.state === null ? emptyState() : validateState(message.state)
        state.schedule_mode = SCHEDULE_MODES.MANUAL
        if (state.state === STATES.QUALIFYING) {
          state.state = STATES.WAITING
          state.qualification_started_at = null
        }
        if (state.state === STATES.HEATING) {
          state.thermostat_low_cycles = 0
          state.active_cycle_tracking_started_at = null
          state.active_cycle_energy_tracking_state = ENERGY_TRACKING_STATES.PAUSED
          state.active_cycle_energy_pause_reason = 'HOUSE_CONSUMPTION_UNAVAILABLE'
        }
        loaded = true
        relayReasserted = false
        rollDailyEnergy(timestamp, actions)
        persist(actions)
        actions.push({ type: 'status', status: status(timestamp, message.state === null ? 'new persistent state' : 'persistent state restored') })
        evaluate(timestamp, actions)
      } catch (error) {
        state = {
          ...emptyState(),
          state: STATES.FAULT_SAFE,
          last_commanded_relay_state: 0
        }
        loaded = true
        relayReasserted = false
        persist(actions)
        actions.push({ type: 'status', status: status(timestamp, `persistent state rejected: ${error.message}`) })
        evaluate(timestamp, actions)
      }
      return actions
    }

    if (!loaded) return actions

    rollDailyEnergy(timestamp, actions)

    if (type === 'soc' || type === 'pv') {
      const value = Number(message.value)
      if (isFiniteNumber(value)) inputs[type] = { value, at: timestamp }
      evaluate(timestamp, actions)
      return actions
    }

    const consumptionTypes = {
      consumption_phase_count: 'consumptionPhaseCount',
      consumption_l1: 'consumptionL1',
      consumption_l2: 'consumptionL2',
      consumption_l3: 'consumptionL3'
    }
    if (Object.prototype.hasOwnProperty.call(consumptionTypes, type)) {
      const value = Number(message.value)
      const validValue = !Array.isArray(message.value) && message.value !== '' &&
        isFiniteNumber(value) && value >= 0 &&
        (type !== 'consumption_phase_count' || (Number.isInteger(value) && value >= 1 && value <= 3))
      inputs[consumptionTypes[type]] = {
        value: validValue ? value : null,
        at: timestamp
      }
      updateActiveCycleTracking(timestamp, actions)
      actions.push({ type: 'status', status: status(timestamp) })
      return actions
    }

    if (type === 'set_heating_power') {
      const requestId = message.requestId === undefined || message.requestId === null
        ? null
        : String(message.requestId)
      const value = Number(message.value)
      const accepted = isFiniteNumber(value) && value >= CONFIG.MIN_HEATING_POWER_W &&
        value <= CONFIG.MAX_HEATING_POWER_W
      state.heating_power_result = {
        requestId,
        accepted,
        errors: accepted ? [] : [`Heating power must be between ${CONFIG.MIN_HEATING_POWER_W} and ${CONFIG.MAX_HEATING_POWER_W} W`]
      }
      if (accepted) state.heating_power_w = value
      updateActiveCycleTracking(timestamp, actions)
      persist(actions)
      actions.push({
        type: 'status',
        status: status(timestamp, accepted ? `heating power set to ${value} W` : 'heating power rejected')
      })
      return actions
    }

    if (type === 'set_heater_mode') {
      const requestId = message.requestId === undefined || message.requestId === null
        ? null
        : String(message.requestId)
      const requestedMode = typeof message.mode === 'string'
        ? message.mode.toUpperCase()
        : String(message.value || '').toUpperCase()
      const accepted = Object.values(SCHEDULE_MODES).includes(requestedMode)
      const errors = accepted ? [] : ['Heater mode must be AUTO or MANUAL']
      if (accepted) {
        state.schedule_mode = requestedMode
        if (requestedMode === SCHEDULE_MODES.MANUAL && state.state === STATES.QUALIFYING) {
          state.state = STATES.WAITING
          state.qualification_started_at = null
        }
      }
      state.schedule_mode_result = {
        requestId,
        mode: state.schedule_mode,
        accepted,
        errors
      }
      persist(actions)
      evaluate(timestamp, actions)
      for (let index = actions.length - 1; index >= 0; index--) {
        if (actions[index].type === 'status') actions.splice(index, 1)
      }
      actions.push({
        type: 'status',
        status: status(timestamp, accepted
          ? `heater schedule mode set to ${state.schedule_mode}`
          : 'heater schedule mode rejected')
      })
      return actions
    }

    if (type === 'manual_start') {
      resetForNewDay(timestamp, actions)
      if (state.state !== STATES.FAULT_SAFE) {
        if (state.state !== STATES.HEATING) startHeating('manual', timestamp, actions)
        else evaluate(timestamp, actions)
      } else {
        commandRelay(0, timestamp, actions, 'manual start rejected in fault-safe')
        actions.push({ type: 'status', status: status(timestamp, 'manual start rejected in fault-safe') })
      }
      return actions
    }

    if (type === 'manual_stop') {
      if (state.state === STATES.FAULT_SAFE) {
        commandRelay(0, timestamp, actions, 'manual stop in fault-safe')
      } else if (state.state === STATES.HEATING) {
        const elapsed = timestamp - state.heating_started_at
        if (state.start_source === 'manual' &&
            elapsed >= 0 && elapsed < CONFIG.EARLY_MANUAL_CANCEL_MS) {
          cancelManualCycle(timestamp, actions)
        } else {
          finishToday(timestamp, actions, 'manual stop completed today', 'MANUAL_STOP')
        }
      } else {
        commandRelay(0, timestamp, actions, 'manual stop while not heating')
        actions.push({ type: 'status', status: status(timestamp, 'manual stop ignored while not heating') })
      }
      return actions
    }

    if (type === 'tick') evaluate(timestamp, actions, { thermostatTick: true })
    return actions
  }

  return {
    handle,
    getState: () => ({ ...state }),
    getConfig: () => ({ ...CONFIG })
  }
}



let runtime = context.get("hotWaterControllerRuntime");
if (!runtime || context.get("hotWaterControllerRuntimeVersion") !== RUNTIME_VERSION) {
  runtime = createHotWaterController();
  context.set("hotWaterControllerRuntime", runtime);
  context.set("hotWaterControllerRuntimeVersion", RUNTIME_VERSION);
}

const topic = msg.topic;
let input;
if (topic === "load") {
  let state = null;
  let error = null;
  if (msg.error && msg.error.code !== "ENOENT") error = msg.error;
  if (!error && typeof msg.payload === "string" && msg.payload.trim()) {
    try { state = JSON.parse(msg.payload); } catch (parseError) { error = parseError; }
  }
  input = { type: "load", state: error ? { invalid: true } : state };
} else if (topic === "soc" || topic === "pv") {
  input = { type: topic, value: Number(msg.payload) };
} else if (["consumption_phase_count", "consumption_l1", "consumption_l2", "consumption_l3"].includes(topic)) {
  input = { type: topic, value: msg.payload };
} else if (topic === "set_heating_power") {
  const payload = msg.payload && typeof msg.payload === "object" ? msg.payload : { value: msg.payload };
  input = { type: topic, value: payload.value, requestId: payload.requestId };
} else if (topic === "set_heater_mode") {
  const payload = msg.payload && typeof msg.payload === "object" ? msg.payload : { mode: msg.payload };
  input = { type: topic, mode: payload.mode || payload.value, requestId: payload.requestId };
} else if (topic === "manual_start" || topic === "manual_stop" || topic === "tick") {
  input = { type: topic };
} else {
  return null;
}

const actions = runtime.handle(input);
const outputs = [null, null, null, []];
for (const action of actions) {
  if (action.type === "persist") outputs[1] = { topic: "persist", payload: JSON.stringify(action.state) };
  if (action.type === "status") { action.status.mode = TEST_MODE ? "TEST_MODE" : "PRODUCTION"; outputs[2] = { topic: "status", payload: action.status.label, hot_water: action.status }; }
  if (action.type === "relay") {
    const trace = { topic: "relay_intent", payload: action.value, reason: action.reason, test_mode: TEST_MODE };
    outputs[3].push(trace);
    if (!TEST_MODE) outputs[0] = { topic: "relay", payload: action.value };
  }
}
if (outputs[3].length === 0) outputs[3] = null;
return outputs;
